# --- 1. PERSISTENT SAVE DATA ---
rank_save_data := class<final><persistable>:
    # Current rank points of the player.
    RankPoints : int = 0
    # Highest tier index the player has reached (the rank-up screen plays once per new tier).
    HighestRankAchieved : int = 0

# Persistent save data of every player.
var RankDataMap : weak_map(player, rank_save_data) = map{}

# --- 2. RANK DATA STRUCTURES ---
rank_tier := class<concrete>:
    # Display name of the tier, for example BRONZE I.
    Name : string = "UNRANKED"
    # Points needed to reach this tier.
    MinPoints : int = 0
    # Rank icon material, if any.
    Icon : ?material = false
    # Color group of the tier (UNRANKED, BRONZE, ... UNREAL).
    ColorGroup : string = "UNRANKED"
    # True only for the last tier.
    IsMaxRank : logic = false

# One line of the leaderboard.
leaderboard_entry := class:
    # The player of this line.
    PlayerObj : player
    # Points of the player.
    Points : int
    # Tier index of the player.
    RankIdx : int
    # Rank icon material of the player, if any.
    Icon : ?material

# --- 3. LOCALIZED MESSAGE HELPERS ---
ToMessage<localizes>(String : string) : message = "{String}"
# Turns a player into a message (their name) for the leaderboard.
PlayerToMessage<localizes>(P : player) : message = "{P}"

# --- 4. SETTINGS CATEGORIES (UEFN DETAILS PANEL) ---
# Category 1: General Settings
general_settings := class<concrete>:
    # Elimination Manager that reports kills and deaths (required).
    @editable EliminationManager : elimination_manager_device = elimination_manager_device{}
    # Points given for each elimination.
    @editable PointsPerKill : int = 15
    # Points taken when the player dies (enter a positive number).
    @editable PointsLostOnDeath : int = 5
    # Show the rank-up screen when a player reaches a new tier.
    @editable EnableRankUpCinematic : logic = true
    # HUD toast (RankUp / RankDown animations); independent from the rank-up cinematic
    @editable EnableRankToast : logic = true
    # Show the live top-5 leaderboard.
    @editable EnableLeaderboard : logic = true

