# Summary: Raduno di polli (Chicken Roundup), round flow: starts the 3 minute timer and shows the end of round message.
# Date: 2026-10-27
# Version: 0.1
using { /Fortnite.com/Devices }
using { /Verse.org/Simulation }
using { /UnrealEngine.com/Temporary/Diagnostics }

chicken_roundup_log := class(log_channel){}

chicken_roundup_device := class(creative_device):
    Logger : log = log{Channel := chicken_roundup_log}

    @editable Timer : timer_device = timer_device{}
    @editable Hud : hud_message_device = hud_message_device{}

    OnBegin<override>()<suspends> : void =
        Timer.SuccessEvent.Subscribe(OnTimerDone)
        Timer.Start()
        Logger.Print("Round started")

    OnTimerDone(MaybeAgent : ?agent) : void =
        Hud.Show()
        Logger.Print("Round over")

# ChickenRoundup.verse
# Summary: Round manager for Chicken Roundup. Players take wildlife chickens and carry them (or tame them so they follow); bringing a chicken into the pen gives ONE point to the player who brought it (HUD, tracker, accolade, native score), with a goal message, a 30-second warning, a winner announcement at time-up and an automatic restart.
# Last modified: 2026-10-29 - v7

using { /Fortnite.com/Devices }
using { /Fortnite.com/Playspaces }
using { /Verse.org/Simulation }
using { /UnrealEngine.com/Temporary/Diagnostics }

# Round states (state machine, no scattered flags)
round_state := enum:
    Lobby
    Playing
    Ended

chicken_roundup := class(creative_device):

    # Centralized logging
    @editable DebugLoggingEnabled : logic = true

    # Devices (editable parameters, linked in the Details panel; single devices are optional so the self-check can see an empty link)
    @editable ChickenSpawners : []wildlife_spawner_device = array{}
    @editable PenSpawner : ?wildlife_spawner_device = false
    @editable PenZone : ?volume_device = false
    @editable PenCaptureArea : ?capture_area_device = false
    @editable RoundTimer : ?timer_device = false
    @editable ScoreManager : ?score_manager_device = false
    @editable ScoreHud : ?hud_message_device = false
    @editable EndHud : ?hud_message_device = false
    @editable GoalTracker : ?tracker_device = false
    @editable ScoreAccolade : ?accolades_device = false
    @editable CelebrationVfx : []vfx_spawner_device = array{}
    @editable CelebrationAudio : ?audio_player_device = false

    # Round state, per-player follower (player -> chicken), chickens already scored, per-player score and display number
    var State : round_state = round_state.Lobby
    var Followers : [agent]agent = map{}
    var Delivered : [agent]logic = map{}
    var Scores : [agent]int = map{}
    var Numbers : [agent]int = map{}
    var NextNumber : int = 1
    var Total : int = 0
    var GoalChanged : logic = false

    # Player-facing texts (plain words)
    ScoreText<localizes>(Count : int) : message = "Your chickens: {Count}"
    StartText<localizes> : message = "Take a chicken and carry it to the pen. Bring as many chickens as you can!"
    WarnText<localizes> : message = "30 seconds left!"
    NobodyText<localizes> : message = "Time is up! Nobody brought a chicken. New round soon."
    WinnerText<localizes>(Name : string, Count : int) : message = "Time is up! The winner is: {Name} with {Count} chickens! New round soon."
    TieText<localizes>(Names : string, Count : int) : message = "Time is up! It is a tie: {Names} with {Count} chickens each! New round soon."
    YouWonText<localizes> : message = "You won this round!"
    GoalTitle<localizes> : message = "Chicken goal"
    GoalFirst<localizes> : message = "Take the first chicken and carry it to the pen"
    GoalMore<localizes> : message = "Bring as many chickens as you can"

    Log(LogMessage : string) : void =
        if (DebugLoggingEnabled?):
            Print(LogMessage)

    # All wildlife spawners that can produce a tameable chicken
    AllSpawners()<transacts> : []wildlife_spawner_device =
        if (Pen := PenSpawner?):
            return ChickenSpawners + array{Pen}
        return ChickenSpawners

    # Wiring: subscribe to the devices, self-check, start the round
    OnBegin<override>()<suspends> : void =
        for (Spawner : AllSpawners()):
            set Spawner.CanTame = true
            Spawner.TamedEvent.Subscribe(OnChickenTamed)
            Spawner.UntamedEvent.Subscribe(OnChickenUntamed)
        if (Zone := PenZone?):
            Zone.AgentEntersEvent.Subscribe(OnEnteredPen)
        if (Area := PenCaptureArea?):
            Area.AgentEntersEvent.Subscribe(OnEnteredPen)
            Area.ItemIsDeliveredEvent.Subscribe(OnItemDelivered)
        if (Timer := RoundTimer?):
            Timer.SuccessEvent.Subscribe(OnTimeUp)
            Timer.StartUrgencyModeEvent.Subscribe(OnUrgency)
        if (Manager := ScoreManager?):
            Manager.Enable()
            Manager.SetScoreAward(1)
            Manager.ScoreOutputEvent.Subscribe(OnScoreOutput)
        GetPlayspace().PlayerAddedEvent().Subscribe(OnPlayerAdded)
        LogWiring()
        StartRound()
        PollDelivery()

    # Self-check read by the kit after the game starts
    LogWiring() : void =
        var PenText : string = "no"
        var ZoneText : string = "no"
        var AreaText : string = "no"
        var HudText : string = "no"
        var TimerText : string = "no"
        var ScoreText2 : string = "no"
        var TrackerText : string = "no"
        var AccoladeText : string = "no"
        if (PenSpawner?):
            set PenText = "yes"
        if (PenZone?):
            set ZoneText = "yes"
        if (PenCaptureArea?):
            set AreaText = "yes"
        if (ScoreHud?, EndHud?):
            set HudText = "yes"
        if (RoundTimer?):
            set TimerText = "yes"
        if (ScoreManager?):
            set ScoreText2 = "yes"
        if (GoalTracker?):
            set TrackerText = "yes"
        if (ScoreAccolade?):
            set AccoladeText = "yes"
        Log("[WIRING] chicken_spawners={ChickenSpawners.Length}/6 pen={PenText} zone={ZoneText} capture_area={AreaText} hud={HudText} vfx={CelebrationVfx.Length}/2 timer={TimerText} score={ScoreText2} tracker={TrackerText} accolade={AccoladeText}")
        if (ChickenSpawners.Length < 6):
            Log("[WIRING] missing: ChickenSpawners has {ChickenSpawners.Length} of 6 entries")
        if (not PenSpawner?):
            Log("[WIRING] missing: PenSpawner")
        if (not PenZone?):
            Log("[WIRING] missing: PenZone")
        if (not PenCaptureArea?):
            Log("[WIRING] missing: PenCaptureArea")
        if (not ScoreHud?):
            Log("[WIRING] missing: ScoreHud")
        if (not EndHud?):
            Log("[WIRING] missing: EndHud")
        if (not GoalTracker?):
            Log("[WIRING] missing: GoalTracker")
        if (not ScoreAccolade?):
            Log("[WIRING] missing: ScoreAccolade")
        if (CelebrationVfx.Length < 2):
            Log("[WIRING] missing: CelebrationVfx has {CelebrationVfx.Length} of 2 entries")

    # A message for everybody on screen
    Announce(Text : message) : void =
        if (Hud := EndHud?):
            Hud.SetText(Text)
            Hud.Show()

    # Round start: reset everything, tell the players the goal, start the clock
    StartRound() : void =
        set State = round_state.Playing
        set Total = 0
        set Followers = map{}
        set Delivered = map{}
        set Scores = map{}
        set GoalChanged = false
        if (Timer := RoundTimer?):
            Timer.Reset()
            Timer.Start()
        if (Manager := ScoreManager?):
            Manager.SetScoreAward(1)
        if (Area := PenCaptureArea?):
            Area.Neutralize()
        if (Tracker := GoalTracker?):
            Tracker.SetTitleText(GoalTitle)
            Tracker.SetDescriptionText(GoalFirst)
            Tracker.SetTarget(1)
            Tracker.SetValue(0)
            Tracker.AssignToAll()
        if (Hud := ScoreHud?):
            Hud.SetText(ScoreText(0))
            Hud.Show()
        Announce(StartText)
        Log("Round started")

    # The score device confirms every point it gives (native score = leaderboard value)
    OnScoreOutput(Player : agent) : void =
        Log("Score device gave a point, native score now: {if (Manager := ScoreManager?) then Manager.GetCurrentScore(Player) else 0}")

    # Late joiners get the goal tracker too
    OnPlayerAdded(Player : player) : void =
        if (Tracker := GoalTracker?):
            Tracker.Assign(Player)

    # 30 seconds left: alarm sound comes from the timer, the message from here
    OnUrgency(MaybeAgent : ?agent) : void =
        if (State = round_state.Playing):
            Announce(WarnText)
            Log("30 seconds warning shown")

    # A player tamed a chicken: remember it as that player's follower (a chicken already delivered is ignored)
    OnChickenTamed(Result : device_ai_interaction_result) : void =
        if (State = round_state.Playing, Player := Result.Source?, Chicken := Result.Target?, not Delivered[Chicken]):
            if (set Followers[Player] = Chicken):
                Log("Tamed: a chicken follows a player")

    # Untamed (by us after a delivery, or by the game): the player follows nothing now
    OnChickenUntamed(Result : device_ai_interaction_result) : void =
        if (Player := Result.Source?):
            ClearFollower(Player)

    ClearFollower(Player : agent) : void =
        var Kept : [agent]agent = map{}
        for (Other -> Chicken : Followers, Other <> Player):
            if (set Kept[Other] = Chicken):
                Log("Kept follower")
        set Followers = Kept

    # Detector 1 (events): the agent entering the pen is a followed chicken
    OnEnteredPen(Agent : agent) : void =
        Log("[DETECT] pen event: something entered, followers known: {Followers.Length}")
        if (State = round_state.Playing):
            if (Owner := FindOwner[Agent]):
                Log("[DETECT] event: the pen saw a followed chicken")
                Deliver(Owner, Agent)

    # Detector 0 (carried chicken): the capture area says which player delivered an item
    OnItemDelivered(Player : agent) : void =
        Log("[DETECT] carried: the pen area received a delivery")
        if (State = round_state.Playing):
            ScorePoint(Player)

    FindOwner(Chicken : agent)<transacts><decides> : agent =
        var Found : ?agent = false
        for (Player -> Followed : Followers, Followed = Chicken):
            set Found = option{Player}
        Found?

    # Detector 2 (every half second): needed because a wildlife chicken may not fire the area events
    PollDelivery()<suspends> : void =
        loop:
            Sleep(0.5)
            if (State = round_state.Playing):
                for (Player -> Chicken : Followers):
                    Method := DetectMethod(Player, Chicken)
                    if (Method <> ""):
                        Log("[DETECT] poll: {Method}")
                        Deliver(Player, Chicken)

    DetectMethod(Player : agent, Chicken : agent) : string =
        if (Zone := PenZone?, Zone.IsInVolume[Chicken]):
            return "pen volume sees the chicken"
        if (Area := PenCaptureArea?, Area.IsInArea[Chicken]):
            return "capture area sees the chicken"
        if (Zone := PenZone?, Zone.IsInVolume[Player]):
            return "the owner stands in the pen with the chicken"
        return ""

    # Display number of a player (Verse has no player-name call)
    NumberOf(Player : agent) : int =
        var Result : int = NextNumber
        if (Existing := Numbers[Player]):
            set Result = Existing
        else:
            if (set Numbers[Player] = NextNumber):
                set NextNumber += 1
        return Result

    Deliver(Player : agent, Chicken : agent) : void =
        if (Delivered[Chicken]):
            return
        if (set Delivered[Chicken] = true):
            Log("Chicken marked as delivered")
        for (Spawner : AllSpawners()):
            Spawner.Untame(Player)
        ClearFollower(Player)
        ScorePoint(Player)

    # One point for a player: score, native score, tracker, accolade, HUD, effects, top-up
    ScorePoint(Player : agent) : void =
        var NewScore : int = 1
        if (Old := Scores[Player]):
            set NewScore = Old + 1
        if (set Scores[Player] = NewScore):
            Log("Player score: {NewScore}")
        set Total += 1
        if (Manager := ScoreManager?):
            Manager.SetScoreAward(1)
            Manager.Activate(Player)
        else:
            Log("[WIRING] ScorePoint: no ScoreManager, native score not given")
        if (Tracker := GoalTracker?):
            Tracker.Increment(Player)
            if (GoalChanged = false):
                set GoalChanged = true
                Tracker.SetDescriptionText(GoalMore)
        if (Accolade := ScoreAccolade?):
            Accolade.Award(Player)
        if (Hud := ScoreHud?):
            Hud.SetText(ScoreText(NewScore))
            Hud.Show(Player)
        spawn:
            PlayCaptureEffect(Player)
        Celebrate()
        TopUpChickens()
        Log("Delivered, total: {Total}")

    # Capture effect of the pen: give control to the player, then clear it again
    PlayCaptureEffect(Player : agent)<suspends> : void =
        if (Area := PenCaptureArea?):
            Area.Neutralize()
            Area.GiveControl(Player)
            Sleep(2.0)
            Area.Neutralize()

    # Top-up: ask every spawner for a replacement so the field never runs dry during a round
    TopUpChickens() : void =
        for (Spawner : AllSpawners()):
            Spawner.Spawn()
        Log("Field topped up")

    # Celebration: restart the effects and play the sound
    Celebrate() : void =
        for (Vfx : CelebrationVfx):
            Vfx.Restart()
        if (Audio := CelebrationAudio?):
            Audio.Play()

    # End of round
    OnTimeUp(MaybeAgent : ?agent) : void =
        EndRound()

    EndRound() : void =
        if (State = round_state.Playing):
            set State = round_state.Ended
            var Best : int = 0
            for (Player -> Points : Scores, Points > Best):
                set Best = Points
            var Winners : []agent = array{}
            if (Best > 0):
                for (Player -> Points : Scores, Points = Best):
                    set Winners += array{Player}
            if (Winners.Length = 0):
                Announce(NobodyText)
            else if (Winners.Length = 1):
                for (Winner : Winners):
                    Announce(WinnerText("Player {NumberOf(Winner)}", Best))
                    if (Hud := ScoreHud?):
                        Hud.SetText(YouWonText)
                        Hud.Show(Winner)
            else:
                var Names : string = ""
                for (Winner : Winners):
                    if (Names = ""):
                        set Names = "Player {NumberOf(Winner)}"
                    else:
                        set Names = "{Names} and Player {NumberOf(Winner)}"
                Announce(TieText(Names, Best))
            Log("Round ended, delivered: {Total}, winners: {Winners.Length}, best: {Best}")
            spawn:
                RestartAfterDelay()

    # The loop never stops: after a pause everything goes back to zero and a new round starts
    RestartAfterDelay()<suspends> : void =
        Sleep(10.0)
        ResetChickens()
        ResetNativeScores()
        StartRound()
        Log("Round restarted")

    ResetChickens() : void =
        for (Spawner : AllSpawners()):
            Spawner.UntameAll()
            Spawner.Reset()
            Spawner.Spawn()

    # The native scoreboard keeps a running score: bring every player back to zero
    ResetNativeScores() : void =
        if (Manager := ScoreManager?):
            for (Player : GetPlayspace().GetPlayers()):
                Current := Manager.GetCurrentScore(Player)
                if (Current > 0):
                    Manager.SetScoreAward(0 - Current)
                    Manager.Activate(Player)
            Manager.SetScoreAward(1)

# weighted_loot_box.verse
# Summary: A button opens a loot box and gives one item chosen by weight (rare items come rarely).
# Last modified: 2026-10-30 - v1

using { /Fortnite.com/Devices }
using { /Verse.org/Simulation }
using { /Verse.org/Random }
using { /UnrealEngine.com/Temporary/Diagnostics }

weighted_loot_box := class(creative_device):

    @editable DebugLoggingEnabled : logic = true
    Log(LogMessage : string):void=
        if (DebugLoggingEnabled?):
            Print(LogMessage)

    # Granters[I] is chosen with the chance Weights[I] / (sum of all Weights). Both lists need the same length.
    @editable OpenButton : button_device = button_device{}
    @editable Granters : []item_granter_device = array{}
    @editable Weights : []int = array{}

    OnBegin<override>()<suspends>:void=
        OpenButton.InteractedWithEvent.Subscribe(OnOpened)

    OnOpened(Agent : agent):void=
        if (Index := PickIndex[], Granter := Granters[Index]):
            Granter.GrantItem(Agent)
            Log("[LOOT] gave entry {Index}")

    PickIndex()<transacts><decides>:int=
        Weights.Length = Granters.Length
        var Total : int = 0
        for (W : Weights):
            set Total += W
        Total > 0
        var Roll : int = GetRandomInt(1, Total)
        var Chosen : int = -1
        for (I -> W : Weights):
            if (Chosen < 0):
                set Roll -= W
                if (Roll <= 0):
                    set Chosen = I
        Chosen >= 0
        Chosen

