# Summary: Runs enemy waves in order: one spawner for each wave, next wave after the last enemy is eliminated, with a pause between waves.
# Last modified: 2026-10-30 - v1

using { /Fortnite.com/Devices }
using { /Verse.org/Simulation }
using { /UnrealEngine.com/Temporary/Diagnostics }

wave_director := class(creative_device):

    @editable DebugLoggingEnabled : logic = true
    Log(LogMessage : string):void=
        if (DebugLoggingEnabled?):
            Print(LogMessage)

    # WaveSpawners[I] spawns wave I; EnemiesPerWave[I] is how many enemies that spawner makes (set the same number on the device).
    @editable WaveSpawners : []wildlife_spawner_device = array{}
    @editable EnemiesPerWave : []int = array{}
    @editable SecondsBetweenWaves : float = 8.0
    @editable WaveHud : hud_message_device = hud_message_device{}

    var Alive : int = 0

    WaveText<localizes>(Number : int, Total : int) : message = "Wave {Number} / {Total}"
    DoneText<localizes> : message = "All waves cleared!"

    OnBegin<override>()<suspends>:void=
        for (Spawner : WaveSpawners):
            Spawner.Disable()
            Spawner.EliminatedEvent.Subscribe(OnEnemyEliminated)
        Sleep(SecondsBetweenWaves)
        for (I -> Spawner : WaveSpawners):
            if (Count := EnemiesPerWave[I]):
                set Alive = Count
                WaveHud.SetText(WaveText(I + 1, WaveSpawners.Length))
                WaveHud.Show()
                Spawner.Enable()
                Log("[WAVE] wave {I + 1} started with {Count} enemies")
                loop:
                    if (Alive <= 0):
                        break
                    Sleep(0.5)
                Spawner.Disable()
                Sleep(SecondsBetweenWaves)
        WaveHud.SetText(DoneText)
        WaveHud.Show()
        Log("[WAVE] all waves cleared")

    OnEnemyEliminated(Result : device_ai_interaction_result):void=
        if (Alive > 0):
            set Alive -= 1

